import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String inputStr = scanner.next();
        StringBuilder outputStr = new StringBuilder();
        boolean hasReplacedAt = false;
        int len = inputStr.length();

        for (int i = 0; i < len; i++) {
            if (i + 1 < len && inputStr.substring(i, i + 2).equals("at") && !hasReplacedAt && i != 0 && i != len - 2) {
                outputStr.append('@');
                hasReplacedAt = true;
                i++;
            } else if (i + 2 < len && inputStr.substring(i, i + 3).equals("dot") && i != 0 && i != len - 3) {
                outputStr.append('.');
                i += 2;
            } else {
                outputStr.append(inputStr.charAt(i));
            }
        }
        System.out.println(outputStr.toString());
        scanner.close();
    }
}
